window.CLES_PARADIS = {"credit":"Traduction : ʿAbbâs Aḥmad al-Bostânî — La Cité du Savoir. Source : Al-Islam.org.","themes":[{"id":"cp1","label":"Les Clés des Paradis · Livre 1 — Petits duʿâʾ et prières","icon":"🗝️","items":[{"type":"header","label":"Pardon et protection"},{"id":"cp1-demande-de-pardon-istigh-far","label":"Demande de pardon (istigh-fâr)"},{"id":"cp1-priere-de-la-peur-de-l-oppresseur","label":"Prière de la peur de l'oppresseur"},{"id":"cp1-conjurer-la-malfaisance-de-la-magie","label":"Conjurer la Malfaisance de la Magie"},{"id":"cp1-recitation-amulette-pour-abolir-l-effet-de-la-ma","label":"Récitation (amulette) pour abolir l’effet de la magie"},{"id":"cp1-demande-de-satisfaction-de-besoins-pressants-et","label":"Demande de satisfaction de besoins pressants et importants"},{"type":"header","label":"Malheurs, jours et nuits"},{"id":"cp1-du-a-contre-les-malheurs-et-les-maladies","label":"Du‘â’ contre les malheurs et les maladies"},{"id":"cp1-des-du-a-pour-tous-les-jours","label":"Des Du‘â’ pour tous les jours"},{"id":"cp1-des-du-a-pour-le-matin-et-le-soir","label":"Des Du‘â’ pour le matin et le soir"},{"id":"cp1-les-prieres-des-jours-de-la-semaine","label":"Les Prières des jours de la semaine"},{"id":"cp1-la-priere-du-samedi","label":"La Prière du Samedi"},{"id":"cp1-la-priere-du-dimanche","label":"La Prière du Dimanche"},{"id":"cp1-la-priere-du-lundi","label":"La Prière du Lundi"},{"id":"cp1-la-priere-du-mardi","label":"La Prière du Mardi"},{"id":"cp1-la-priere-du-mercredi","label":"La Prière du Mercredi"},{"id":"cp1-la-priere-du-jeudi","label":"La Prière du Jeudi"},{"id":"cp1-la-priere-du-vendredi","label":"La Prière du Vendredi"},{"type":"header","label":"Les morts"},{"id":"cp1-la-priere-de-la-nuit-de-l-enterrement","label":"La Prière de la nuit de l’enterrement"},{"id":"cp1-devoirs-envers-les-morts","label":"Devoirs envers les morts"},{"type":"header","label":"Faim, doute et pardon"},{"id":"cp1-la-priere-de-l-affame","label":"La prière de l’affamé"},{"id":"cp1-priere-contre-le-scepticisme-les-tentations-de-s","label":"Prière contre le scepticisme, les tentations de Satan et le doute obsessionnel"},{"id":"cp1-priere-de-demande-de-pardon-des-peches-istigh-fa","label":"Prière de demande de pardon des péchés (istigh-fâr)"},{"type":"header","label":"L'Istikhâra"},{"id":"cp1-la-priere-de-l-istikharah-au-tirage-au-sort","label":"La Prière de l’Istikhârah au tirage au sort"},{"id":"cp1-d-autres-methodes-de-faire-l-istikharah","label":"D’autres méthodes de faire l’Istikhârah"},{"id":"cp1-istikharah-ou-presage-par-le-coran","label":"Istikhârah ou présage par le Coran"},{"id":"cp1-istikharah-par-le-chapelet-et-le-nombre","label":"Istikhârah par le chapelet et le nombre"},{"id":"cp1-l-istikharah-consultation-divine-d-apres-le-prop","label":"L’Istikhârah (consultation divine) d’après le Prophète (P)"},{"type":"header","label":"Besoins, subsistance et dettes"},{"id":"cp1-invocation-lors-de-la-circoncision","label":"Invocation lors de la circoncision"},{"id":"cp1-la-priere-du-besoin","label":"La Prière du besoin"},{"id":"cp1-priere-pour-se-sortir-d-une-situation-difficile","label":"Prière pour se sortir d’une situation difficile"},{"id":"cp1-priere-pour-augmenter-les-moyens-de-subsistance","label":"Prière pour augmenter les moyens de subsistance (rizq)"},{"id":"cp1-du-a-pour-le-rizq-moyen-de-subsistance","label":"Du‘â’ pour le rizq (moyen de subsistance)"},{"id":"cp1-du-a-pour-s-acquitter-des-dettes","label":"Du‘â’ pour s’acquitter des dettes"}]},{"id":"cp3","label":"Les Clés des Paradis · Livre 3 — Les Ziyâra","icon":"🗝️","items":[{"type":"header","label":"Ziyârât particulières"},{"id":"z-warith","label":"Ziyārat Wārith"},{"type":"header","label":"ʿĀshūrā et ʿAlqama"},{"id":"z-ashura","label":"Ziyārat 'Āshūrā"}]},{"id":"cp4","label":"Les Clés des Paradis · Livre 4 — Les grands duʿâʾ","icon":"🗝️","items":[{"id":"kumayl","label":"Du'ā Kumayl"},{"id":"makarem","label":"Makārim al-Akhlāq (Ṣaḥīfa 20)"},{"id":"tawassul","label":"Du'ā at-Tawassul"}]}],"invocations":{"cp1-demande-de-pardon-istigh-far":{"source":"Les Clés des Paradis — Livre 1","title":"Demande de pardon (istigh-fâr)","body":[{"t":"instruction","tx":"■ Selon l'Imam al-Sâdiq (p), il n'est pas de croyant qui, commettant chaque jour ou chaque nuit jusqu'à quarante péchés majeurs, se repente sincèrement en récitant l'Istigh-fâr suivant sans qu'Allah ne lui pardonne (ses péchés):"},{"t":"tri","ar":"اَسْتَغْفِرُ اللَّه الّذي لا اِلهَ اِلأ هُوَ الحَيُّ القَيُّومُ بَديعُ السَّماواتِ والاَرْضِ ذُو الْجَلالِ وَالاِكْرام وَ أَسْأَلُهُ أنْ يَتُوبَ عَلَيَّ","tr":"Astagh-fir-ullâh-al-lathî lâ ilâha illâ huwa-l-Hayy-ul-Qayyûmu, Badî`-ul-samâwâti wa-l-ardhi, thu-l-Jalâli wa-l-Ikrâmi, wa as'aluhu an yatûba `alayya.","fr":"Je demande pardon à Allah, en dehors Duquel il n'y a d'autre Divinité que Lui, le Vivant, l'Auto-subsistant, le Créateur des cieux et de la terre, le plein-de-Majesté et de Munificence, et je me repens auprès de Lui."}]},"cp1-priere-de-la-peur-de-l-oppresseur":{"source":"Les Clés des Paradis — Livre 1","title":"Prière de la peur de l'oppresseur","body":[{"t":"instruction","tx":"Cette prière fut accomplie par le Prophète (P) le jour de la Bataille d'Ohod. Elle s'accomplit comme suit: On commence par l'accomplissement d'un ghusl (ablution majeure) suivi de deux rak`ah de prière, et puis sur place on découvre le genou en récitant cent fois:"},{"t":"tri","ar":"يا حيُّ يا قَيُّوم يا حَيُّ لا اِلـهَ إلاّ اَنْتَ بِرَحْمَتِكَ اَسْتَغيثُ فَصَلِّ عَلى مُحَمَّد وَ آلِ مُحَمَّد وَاَغِثْني السّاعَةَ السّاعَةَ","tr":"Yâ Hayyu yâ Qayyûm, yâ Hayyu lâ ilâha illâ anta bi-Rahmatika astaghîthu. Façalli `alâ Muhammadin wa Âle Muhammadin, wa aghithnî, assâ`ata, assâ`ata","fr":"O le Vivant, O l'Auto-Subsistant! O Toi le Vivant en dehors de qui il n'y a d'autre Divinité que Toi. Prie donc sur Muhammad et sur les Membres de sa Famille, et secours-moi maintenant, maintenant!"},{"t":"instruction","tx":"Puis on récite une fois:"},{"t":"tri","ar":"اَنْ تُصَلِّيَ عَلى مُحَمَّد وَآلِ مُحَمَّدٍ وَ اَنْ تَلْطُفَ بي اَنْ تَغْلِبَ لي واَنْ تَمْكُرَ لي وَ اَنْ تَخْدَعَ لي وَاَنْ تَكفيني مَؤونةَ ...فلان ابن فلان","tr":"Allâhumma as'aluka an tuçallî `alâ Muhammadin wa Âle Muhammadin wa an taltufa bî wa an tagh-liba lî wa an tamkura lî wa an takh-da`a lî wa an takfînî ma'ûnata ……..Untel fils d'Untel (prononcez le nom de l'oppresseur)","fr":"O mon Dieu! Je Te demande de prier sur Muhammad et sur les Membres de sa Famille, et de m'accorder Ta Grâce, d'user de stratagème en ma faveur, de tromper (l'oppresseur) pour moi et de m'épargner la provision de bouche (ou l'humiliation) d'Untel fils d'Untel (prononcer le nom complet de l'oppresseur)"}]},"cp1-conjurer-la-malfaisance-de-la-magie":{"source":"Les Clés des Paradis — Livre 1","title":"Conjurer la Malfaisance de la Magie","body":[{"t":"instruction","tx":"Le Prophète (P) dit, en s'adressant à l'Imam Ali (p):"},{"t":"instruction","tx":"\"O Alî (Ibn Abî Tâlib)! Quiconque appréhende un magicien ou un diable qu'il récite ce verset coranique:"},{"t":"tri","ar":"إِنَّ رَبَّكُمْ اللَّهُ الَّذِي خَلَقَ السَّمَاوَاتِ وَالأَرْضَ فِي سِتَّةِ أَيَّامٍ ثُمَّ اسْتَوَى عَلَى الْعَرْشِ يُدَبِّرُ الأَمْرَ مَا مِنْ شَفِيعٍ إِلاَّ مِنْ بَعْدِ إِذْنِهِ ذَلِكُمْ اللَّهُ رَبُّكُمْ فَاعْبُدُوهُ أَفَلاَ تَذَكَّرُونَ (سورة يونس: 3/10(","tr":"Inna Rabbakum-Allâhu-lathî khalaqa-s-samâwâti wa-l-ardha fî sittati ayyâmin thumma-stawâ ‘alâ-l-‘archi yudabbiru-l-amra mâ min chafî‘in illâ min ba‘da ithnihi thâlikum Allâhu Rabbukum fa-‘budûhu afalâ tathakkarûn-a","fr":"“Votre Seigneur est Dieu qui a créé les cieux et la terre en six jours; puis IL s'est assis en Majesté sur le Trône. IL dirige toute chose avec attention. Il n'y a d'intercesseur qu'avec Sa permission. Tel est Dieu, votre Seigneur! Adorez-Le donc! Ne réfléchissez-vous pas?” (Sourate 10, verset 3)"}]},"cp1-recitation-amulette-pour-abolir-l-effet-de-la-ma":{"source":"Les Clés des Paradis — Livre 1","title":"Récitation (amulette) pour abolir l’effet de la magie","body":[{"t":"instruction","tx":"Selon l’Imam Ali, pour conjurer l’effet de la magie, écrivez les mots suivants sur une feuille et portez-la sur vous:"},{"t":"tri","ar":"بِسْمِ اللهِ وَ بِاللهِ بِسْمِ اللهِ وَ ماشآءَ اللهُ بِسْمِ اللهِ وَ لاحَوْلَ وَلاقُوَّةَ اِلاّ بِاللهِ \" قالَ مُوسَى: ما جِِئْتُم بِهِ الْسِّحْرُ اِنَّ اللَّه سَيُبْطِلُهُ اِنّ اللَّهَ لا يُصْلِحُ عَمَلَ المُفْسِدين. فَوَقَعَ الْحَقُّ وَبَطَلَ مَا كَانُوا يَعْمَلُونَ (118) فَغُلِبُوا هُنَالِكَ وَانقَلَبُوا صَاغِرِينَ (119) \"سورة الاعراف:7/118-119","tr":"Bism-illâhi wa billâhi, bism-illâhi mâ châ’Allâhu, bism-illâhi wa lâ hawla wa lâ quwwata illâ billâhi. «Qâla Mûsâ: Mâ ji’tum bihi-s-sihru inna-llâha sa-yubtiluhu, inna-llâha lâ yuçlihu ‘amal-al-mufsidîn-a. Fawaqa‘a-l-haqqu wa batala mâ kânû ya‘malûn-a, faghulibû hunâlika wa-nqalabû çaghirîn-a »","fr":"voir: sourate al-A‘râf: 7/118-119"},{"t":"intro","tx":"(Au Nom d’Allah et par Allah, au Nom d’Allah et la Volonté d’Allah qui prévaut, au Nom d’Allah, et il n’y a de Pouvoir ni de Force en dehors d’Allah. Mûsâ (Moïse) dit: “Allah abolira l’effet de la magie que vous avez apportée. \"Ainsi la vérité se manifesta et ce qu’ils firent fut vain. Ainsi, ils furent battus et se trouvèrent humiliés\" (sourate al-A‘râf: 7/118-119)”)"}]},"cp1-demande-de-satisfaction-de-besoins-pressants-et":{"source":"Les Clés des Paradis — Livre 1","title":"Demande de satisfaction de besoins pressants et importants","body":[{"t":"instruction","tx":"Lorsqu’on a une demande importante à formuler à l’adresse d’Allah, on écrit ce qui suit sur un papier qu’on jettera dans un cours d’eau:"},{"t":"tri","ar":"بِسْمِ اِللهِ الرَّحْمنِ الرَّحيم. مِن العَبْدِ الذَّليل اِلى المولى الجَليل: رَبّي اِنّي مَسَّني الضُّرُّ وَاَنْتَ اَرْحَمُ الرَّاحِمينَ. بِحَقِّ مُحَمَّدٍ وَ آلِهِ صَلِّ عَلى مُحَمَّدٍ وَآلِهِ وَكْشِف عَنّي هَمّي وَفَرِّج عَنّي غَمّي بِرَحْمَتِكَ يا اَرْحَمَ الرّاحِمينَ","tr":"Bism-illâh-ir-Rahmân-ir-Rahîm. Min-al-‘abd-ith-thalîl ilâ-l-Mawlâ-l-Jalîl: Rabbi innî massanî-dh-dhuru wa Anta Arham-ar-Râhimîn-a. Bi-haqqi Muhammadin wa Âlihi çalli ‘alâ Muhammadin wa Âlihi, wa-k-chif ‘annî hammî wa farrij ‘annî ghammî bi-Rahmatika yâ Arham-ar-Râhimîn-a","fr":"Au Nom d’Allah, le Clément, le Miséricordieux. Du serviteur humilié au Maître auguste: O mon Seigneur! Le malheur m’a touché, mais Tu es le plus Miséricordieux des miséricordieux. Par l’amour de Muhammad et la Famille de Muhammad, prie sur Muhammad et la Famille de Muhammad et dissipe mon souci et écarte de moi mon affliction, par Ta Miséricorde, O Toi le plus Miséricordieux des miséricordieux!"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p), si on a un voeu dont on veut demander à Allah la réalisation, ou qu’on craint un malheur ou encore qu’on a peur de quelque chose, on écrit sur un papier blanc l’invocation suivante, on le plie et on l’insère dans une noix de boue qu’on jette dans un cours d’eau:"},{"t":"tri","ar":"بِسْمِ اللهِ الرَّحْمنِ الرَّحيمِ، اللّـهُمَّ اِنّي اَتَوَجَّهُ اِلَيْكِ بِاَحَبِّ الاَْسْماءِ اِلَيْكَ وَاَعْظَمِها لَدَيْكَ، وَاَتَقَرَّبُ وَاَتَوَسَّلُ اِلَيْكَ بِمَنْ اَوْجَبْتَ حَقَّهُ عَلَيْكَ، بِمُحَمَّد وَعَلِي وَفاطِمَةَ وَالْحَسَنِ وَالْحُسَيْنِ وَعَلِي بْنِ الْحُسَيْنِ وَمُحَمَّدِ بْنِ عَلِي وَجَعْفَرَ بْنِ مُحَمَّد وَمُوسَى بْنِ جَعْفَر وَعَلِي بْنِ مُوسى وَمُحَمَّدِ بْنِ عَلِي وَعَلِي بْنِ مُحَمَّد وَالْحَسَنِ بْنِ عَلِي وَالْحُجَّةِ الْمُنْتَظَرِ صَلَواتُ اللهِ عَلَيْهِمْ اَجْمَعينَ اكْفِني كَذا وَكَذا.)أي اذكر حاجتك، ثمّ تطوي الرّقعة وتجعلها في بندقة طين وتطرحها في ماء جار أو بئر فانّه تعالى يفرج عنك(.","tr":"Allâhumma innî atawajjahu ilayka bi-ahab-bil-asmâ’i ilayka wa a‘dhamihâ ladayka wa atawassalu ilayka bi-man awjabta haqqahu ‘alayka bi-Muhammadin wa ‘aliyyin wa Fâtimata wa-l-Hasani wa-l-Husayni wa ‘Aliyy-in-ibn-il-Husayni wa Muhammadin-ibn-i ‘Aliyyin wa Ja‘far-in-ibn-i Muhammad-in wa Mûsâ-bni Ja‘far-in wa ‘Aliyy-in-ibn-i Mûsâ wa Muhammadin-ibn-i ‘Aliyy-in wa ‘Aliyy-in ibn-i Muhammad-in wa-l-Hasan-ibn-i ‘Aliyy-in wa-l-Hujjat-il-Muntadhar-i, çalawât-ullâhi ‘alayhim ajma‘în (et là on formule le voeu ou mentionne le besoin dont on demande à Allah l’exaucement).","fr":"O Allah! Je m’adresse à Toi par les noms les plus aimés de Toi et les plus considérés par Toi, et je sollicite Ta proximité et je T’implore par l’amour de ceux dont Tu as rendu le droit obligatoire sur Toi: par Muhammad et Ali et Fâtimah et al-Hasan et al-Husayn et ‘Ali ibn-il-Husayn et Muhammad-ibni ‘Ali et Ja‘far ibn Muhammadin et Mûsâ ibn Ja‘far et ‘Ali ibn Mûsâ et Muhammad ibn ‘Ali et ‘Ali ibn Muhammad et al-Hasan ibn ‘Ali et al-Hujjat-il-Muntadhar (l’Argument attendu = l’Imam al-Mahdi). Que Tes Prières soient sur eux tous, pour Te demander (et là on formule ses voeux ou son besoin)"}]},"cp1-du-a-contre-les-malheurs-et-les-maladies":{"source":"Les Clés des Paradis — Livre 1","title":"Du‘â’ contre les malheurs et les maladies","body":[{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p) quiconque dit chaque jour cent fois:"},{"t":"tri","ar":"لا حَوْلَ وَلا قُوَّةَ اِلاّ بِاللَّه","tr":"Lâ hawla wa lâ quwwata illâ billâh","fr":"Il n’y a ni force ni pouvoir en dehors d’Allah,"},{"t":"intro","tx":"Allah éloigne de lui 70 malheurs dont le moins dur est le souci."},{"t":"instruction","tx":"■ Selon le Prophète (P): « Quiconque dit 100 fois chaque jour:"},{"t":"tri","ar":"لااِلهَ اِلأ اللهُ المَلِكُ الحَقُّ المُبين","tr":"Lâ Ilâha illâllâhu-l-Malik-ul-Haqq-ul-Mubîn","fr":"Il n’y a de Dieu qu’Allah, le Roi, la Vérité Évidente"},{"t":"intro","tx":"sera à l’abri de la pauvreté, aura une assurance contre la solitude terrorisante de la tombe, et cela lui apportera la richesse et lui ouvrira les portes du paradis»"},{"t":"intro","tx":"Du‘â’ lors d’un Enlisement"},{"t":"instruction","tx":"Le Prophète (P) dit à Ali (p):"},{"t":"instruction","tx":"«Si tu te trouves dans un enlisement dis:"},{"t":"tri","ar":"بِسْمِ اِللهِ الرَّحْمنِ الرَّحيم. لا حَوْلَ وَلا قُوَّةَ اِلاّ بِاللَّهِ العَليِّ العَظيم. اِيَّاكَ نَعْبُدُ وَ اِيَّاك نَسْتَعين","tr":"Bism-illâh-ir-Rahmân-ir-Rahîm. Lâ hawla wa lâ quwwata illâ billâh-il-‘Aliyy-il-‘Adhîm. Allâhumma Iyyâka na‘budu wa Iyyâka nasta‘în","fr":"Au Nom d’Allah, le Clément, le Miséricordieux. Il n’y a de force ni de pouvoir en dehors d’Allah, le Sublime, le Très-Haut. O Allah! C’est Toi que nous adorons, et c’est Toi dont nous implorons secours."},{"t":"intro","tx":"Allah - IL est Sublime - conjure ton épreuve »."}]},"cp1-des-du-a-pour-tous-les-jours":{"source":"Les Clés des Paradis — Livre 1","title":"Des Du‘â’ pour tous les jours","body":[{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p) quiconque dit chaque jour 25 fois l’invocation suivante, Allah lui efface un nombre de péchés égal au nombre de chaque croyant passé et de chaque croyant qui reste jusqu’au Jour du Jugement, et Il le relève d’un degré:"},{"t":"tri","ar":"اَللَّهُمَّ اغْفِرلِلمُؤْمِِنينَ والمُؤْمِناتِ وَالمُسْلِمِينَ وَ المُسْلِماتِ","tr":"Allâhumma-gh-fir il-l-mu’minîna wa-l-mu’minâti wa-l-muslimîna wa-l-muslimâti","fr":"(O mon Dieu! Pardonne aux croyants et aux croyantes, aux musulmans et aux musulmanes)."},{"t":"intro","tx":"■ Selon l’Imam al-Sâdiq (p) toujours, le Prophète (P) avait l’habitude de dire chaque jour 70 fois “Astagh-fir-ullâh” أَسْتَغْفِرُ اللَّه (je demande pardon à Allah) et 70 fois: “Atûbu ilâllâh” أَتوبُ أِلى اللَّه (je me repens auprès d’Allah)."},{"t":"instruction","tx":"* Selon l’Imam al-Sâdiq (p) quiconque dit chaque jour cent fois:"},{"t":"tri","ar":"لا حَوْلَ وَلا قُوَّةَ اِلاّ بِاللَّه","tr":"Lâ hawla wa lâ quwwata illâ billâh","fr":"Il n’y a ni force ni pouvoir en dehors d’Allah,"},{"t":"intro","tx":"Allah éloigne de lui 70 malheurs dont le moins dur est le souci."},{"t":"intro","tx":"■ Selon le Prophète (P): « Quiconque dit 100 fois chaque jour l’invocation suivante sera à l’abri de la pauvreté, aura une assurance contre la solitude terrorisante de la tombe, et cela lui apportera la richesse et lui ouvrira les portes du paradis»"},{"t":"tri","ar":"لا اَِلَهَ اِلاّ اللَّهُ المَلِكُ الحَقُّ المُبين","tr":"Lâ Ilâha illâllâhu-l-Malik-ul-Haqq-ul-Mubîn","fr":"Il n’y a de Dieu qu’Allah, le Roi, la Vérité Évidente"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p), le Prophète (P) dit: «Quiconque désirerait que son éloge soit placé au-dessus de celui des mujâhidine (les combattants pour la Cause d’Allah), par les Anges rapprochés (al-Mala’ al-a‘lâ), qu’il lise chaque jour la récitation ci-après. Ce faisant, son besoin sera satisfait, s’il en a un, son ennemi sera refoulé, sa dette acquittée, son affliction disparue, et sa récitation traversera les sept ciels pour atteindre la Table gardée (al-Lawh al-Mahfûdh):"},{"t":"tri","ar":"سُبْحانَ اللهِ كَما يَنْبَغي للهِِ وَالْحَمْدُللهِِ كَما يَنْبَغي للهِِ وَ لا اِلهَ اِلاّ اللهُ كَما يَنْبَغي للهِِ وَاللهُ اَكْبَرُ كَما يَنْبَغي للهِِ وَ لا حَوْلَ وَ لا قُوَّةَ اِلاّ بِاللهِ وَ صَلَّى اللهُ عَلى مُحَمَّد النَّبِي وَ عَلى اَهْلِ بَيْتِهِ وَ جَميعِ الْمُرْسَلينَ وَالنَّبِيّينَ حَتّى يَرْضَى اللهُ *","tr":"Subhân-Allâhi kamâ yanbaghî lillâhi wa-l-Hamdu lillâhi kamâ yanbaghî, wa lâ ilâha illâllâhu kamâ yanbaghî lillâhi wa-llâhu Akbaru kamâ yanbaghî lillâhi, wa lâ hawla wa lâ quwwata illâ bi-llâhi, wa çallâ-llâhu ‘alâ Muhammadin wa ‘alâ ahli baytihi wa jamî‘-il-mursalîna wa-l-nabiyyîna hattâ yardhâ-llâh","fr":"(Gloire à Allah comme cela se doit à Allah, louanges à Allah comme cela se doit, et il n’y a de Dieu qu’Allah, comme cela se doit à Allah, Allâh est le plus Grand, comme cela se doit à Allah, et il n’y a de force ni de pouvoir si ce n’est par Allah, et Allah a prié sur Muhammad et sur les membres de sa Famille, ainsi que sur tous les Messagers et les Prophètes, et ce jusqu’à ce qu’Allah agrée)»."},{"t":"instruction","tx":"■ Selon le Prophète (P): «Quiconque dit chaque jour dix fois l’invocation suivante, se purifiera de ses péchés comme le jour où sa mère l’a mis au monde. De plus lui seront épargnées 70 sortes de malheurs dont la folie, l’éléphantiasis, la lèpre, l’hémiplégie, et Allah lui affecte 70 mille anges qui demanderont le pardon pour lui»:"},{"t":"tri","ar":"بِسْمِ اِللهِ الرَّحْمنِ الرَّحيم لا حَوْلَ وَلا قُوَّةَ اِلاّ بِاللَّهِ العليِّ العَظيم","tr":"Bism-illâh-ir-Rahmân-ir-Rahîm. Lâ hawla wa lâ quwwata illâ billâh-il-‘Aliyy-il-‘Adhîm","fr":"Au Nom d’Allah, le Clément, le Miséricordieux. Il n’y a de force ni de pouvoir en dehors d’Allah, le Très-Haut, le Sublime."},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p) cité par al-Kulaynî, le Prophète (P) disait chaque jour 360 fois (au nombre des veines du corps):"},{"t":"tri","ar":"الحَمْدُ لِلّهِ رَبِّ العاَلمينَ كثيراً عَلى كُلِّ حال","tr":"Al-hamdu lillâhi Rabb-il-‘âlamîna kathîran ‘alâ kulli hâl","fr":"Des multitudes de louanges à Allah, Seigneur des mondes dans tous les cas"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p): “Quiconque dit 400 fois par jour, pendant deux mois consécutifs l’invocation suivante, Allah le dotera de beaucoup de savoir ou de beaucoup de richesse:"},{"t":"tri","ar":"اَسْتَغْفِرُ اللَّه الّذي لا اِلهَ اِلأ هُوَ الحَيُّ القَيُّومُ الرَّحْمنُ الرَّحيمُ بَديعُ السَّماواتِ والاَرْضِ مِنْ جَميعِ ظُلْمي وَ جُرْمي وَ اِسْرافي على نَفْسي وَ اَتوبُ اِليْهِ","tr":"Astagh-fir-ullâh-al-lathî lâ ilâha illâ Huwa-l-Hayy-ul-Qayyûm-ur-Rahmân-ur-Rahîmu, Badî‘-us-samâwâti wa-l-ardhi, min jamî‘i dhulmî wa jurmî wa isrâfî ‘alâ nafsî wa atûbu ilayhi","fr":"Je demande pardon à Allah, Celui en dehors de Qui il n’y a de Dieu que Lui, le Vivant, le Sustentateur, le Clément, le Miséricordieux, le Créateur des ciels et de la Terre, de l’ensemble de mon injustice, mes crimes et de mes abus vis-à-vis de moi-même, et je retourne vers Lui"},{"t":"instruction","tx":"■ Quiconque dit sept fois l’invocation suivante, Allah éloigne de lui les soucis de ce monde et de l’Autre-Monde:"},{"t":"tri","ar":"حَسْبِيَ اللهُ لااِلـهَ اِلاّ هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظيمِ.","tr":"Hasb-iy-Allâhu Rabbî, Allâhu lâ ilâha illâ Huwa, ‘alayhi tawakkaltu wa-Huwa Rabb-ul-‘Arch-il-‘Adhîm","fr":"Allah, mon Seigneur me suffit, Allah, il n’y a de divinité que Lui. En Lui je place ma confiance; et Il est le Seigneur du Trône immense"}]},"cp1-des-du-a-pour-le-matin-et-le-soir":{"source":"Les Clés des Paradis — Livre 1","title":"Des Du‘â’ pour le matin et le soir","body":[{"t":"instruction","tx":"■ L’Imam al-Sâdiq (p) dit: “Ne négligez jamais de dire trois fois chaque matin et chaque soir:"},{"t":"tri","ar":"اَللّهُمَّ اجْعَلني في دِرْعِكَ الْحَصينَةِ الّتي تَجْعَلُ فيها مَنْ تُريدُ","tr":"Allâhumma-j‘alnî fî Dir‘ik-al-Haçînah allatî taj‘ala fîhâ man turîd-u","fr":"O Allah! Mets-moi dans Ta Cuirasse fortifiée dans laquelle Tu mets qui Tu voudrais,"},{"t":"intro","tx":"car cette invocation fait partie des du‘â’ renfermant les mystères d’Allah”"},{"t":"instruction","tx":"■ L’Imam Muhammad al-Taqî (p) dit: “Dis chaque matin et chaque soir:"},{"t":"tri","ar":"اللهُ اللهُ اللهُ رَبّي الرَّحمنُ الرَّحيمُ لا اُشرِكُ بِهِ شيْئاً","tr":"Allâh! Allâh! Allâh Rabbî! Ar-Rahmân-ur-Rahîm-u! Lâ uchriku bihi chay’an","fr":"Allah, Allah, Allah est mon Seigneur, le Très-Miséricordieux, le Tout-Miséricordieux, à Qui je n’associe rien,"},{"t":"intro","tx":"puis formule les voeux que tu désires, car cette invocation est le préliminaire de tout du‘â’”"},{"t":"instruction","tx":"■ Selon l’Imam al-Bâqir (p): “Quiconque fait l’invocation suivante au lever de l’aube, ne sera pas inscrit au nombre des insouciants au cours de la journée, et quiconque la récite la nuit ne sera pas inscrit au nombre des insouciants au cours de cette nuit:"},{"t":"tri","ar":"لا اَِلَهَ اِلاّ اللَّهُ وَحْدَهُ لاشَريكَ لَهُ، لَهُ المُلكُ وَ لَهُ الحَمْدُ، يُحيي وَ يُميِتُ وَهُوَحَيٌّ لا يَمُوتُ، بِيَدِهِ الخَيْرُوَهُوَ عَلي كُلِّ شَيءٍ قَديرٌ.","tr":"1- “Lâ ilâha illâ-llâhu, Wahdahu lâ charîka lah-u! Lahu-l-Mulk-u wa lahu-l-Hamdu! Yuhyî wa yumît-u, wahuwa Hayyun lâ yamût-u. Bi-yadih-il-Khayr-u wahuwa ‘alâ kulli chay’in Qadîr-un” (10 fois)","fr":"Il n’y a de Dieu qu’Allah! Il est Un, sans associé! Lui appartient le Royaume et Lui appartient la Louange! Il fait vivre et Il fait mourir, mais Il est toujours Vivant et ne meurt jamais. Le Bien est entre Ses Mains et Il a le Pouvoir sur toute chose"},{"t":"tri","ar":"صلّى اللَّهُ على مُحَمَّدٍ وَ آلِ مُحَمَّدٍ","tr":"2-“çallâ-llâhu ‘alâ Muhammadin wa Âle Muhammadin” (10 fois)","fr":"Allah prie sur Muhammad et sur les membres de la Famille de Muhammad"},{"t":"tri","ar":"سُبْحان اللَّهُ","tr":"3-“Subhân-Allâh-u” (35 fois)","fr":"Gloire à Allah"},{"t":"tri","ar":"لا اِلَهَ اِلاّ اللَّهُ","tr":"4- “Lâ ilâha illâ-llâh-u” (35 fois)","fr":"Il n’y a de Dieu qu’Allah"},{"t":"intro","tx":"5- “Al-Hamdu lillâh-i” (35 fois)"},{"t":"tri","ar":"الحَمْدُ لِلّهِ","fr":"Louanges à Allah"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p), l’Imam Ali ibn al-Hussayn (p) récitait l’invocation suivante, lorsqu’il commençait sa journée:"},{"t":"tri","ar":"اَبْتَدِءُ يَوْمي هذا بَيْنَ يَدَي نِسْياني وَ عَجَلَتي بِسْمِ اللهِ وَ ما شآءَ اللهُ","tr":"Abtadî’u yawmî hâthâ bayna yaday nisyânî wa ‘ajalatî: bism-illâh-i wa mâ châ’Allah-u","fr":"Je commence ma journée que voici, en devançant mon oubli et ma hâte, par: Au Nom d’Allâh et ce que veut Allâh"},{"t":"instruction","tx":"■ L’Imam al-Sâdiq (p) dit: “Quiconque récite 3 fois l’invocation suivante, le soir, sera entouré (protégé) de l’une des ailes de Jibrâ’îl (l’Archange Gabriel) jusqu’au matin:"},{"t":"tri","ar":"اَسْتَوْدِعُ اللهَ الْعَلِي الاَْعْلَى الْجَليلَ الْعَظيمَ نَفْسي وَ مَنْ يَعنْيني اَمْرُهُ اَسْتَوْدِعُ اللهَ نَفْسِيَ الْمَرْهُوبَ الْمَخُوفَ الْمُتَضَعْضَعَ لِعَظَمَتِهِ كُلُّ شَيْئ","tr":"Astawdi‘-ullâh-al-‘Aliyy-al-A‘lâ, Al-Jalîl-al-‘Adhîm-a, nafsî wa man yu‘nînî amruhu! Astawdi‘u-llâh-a nafsî-l-marhûb-al-makhûf-al-mutadha‘dhi‘a li-‘Adhamatihi kullu chay’-in","fr":"Je confie à Allah, le Très-Haut, le Plus-Haut, le Majestueux, l’Immense, moi-même et toute personne dont le sort me soucie! Je me confie à Allah devant l’Immensité Duquel toute chose est terrifiée, craintive et ébranlée"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p) encore: Lorsque le soir se pointe, récitez l’invocation suivante et présentez ensuite à Allah tous les voeux que vous désireriez:"},{"t":"tri","ar":"اَللّهُمَّ اِنّي اَسْئَلُكَ عِنْدَ اِقْبالِ لَيْلِكَ وَ اِدْبارِ نَهارِكَ وَ حُضُورِ صَلَواتِكَ وَ اَصْواتِ دُعآئِكَ اَنْ تُصَلِّي عَلى مُحَمَّد وَ آلِ مُحَمَّدٍ","tr":"Allâhumma innî as’aluka ‘inda iqbâli Laylika wa idbâri Nahârika wa hudhûri çalawâtika wa açwâti du‘â’ika an tuçallî ‘alâ Muhammadin wa Âle Muhammad-in","fr":"O Allah! Je Te demande au moment de la venue de Ta nuit et du départ de Ton jour, de la présence de Tes prières et des voix de Ton Du‘â’, de prier sur Muhammad et sur les membres de sa Famille"},{"t":"intro","tx":"■ Abu-l-Dardâ’ rapporte qu’un jour quelqu’un vint lui annoncer que sa maison venait d’être incendiée, mais qu’il lui affirma avec certitude qu’une telle chose n’aurait pas pu se produire. Lorsqu’une autre personne se présenta à lui et confirma la nouvelle de l’incendie de sa maison il afficha la même certitude quant à l’impossibilité de l’occurrence d’un tel événement. Une troisième personne lui annonça la même mauvaise nouvelle, mais il persista à récuser cette nouvelle."},{"t":"instruction","tx":"Or, on apprit par la suite qu’une série de maisons au milieu desquelles figurait la sienne avaient été incendiées, à l’exception de celle-ci. Lorsqu’on lui demanda comment il savait que sa maison n’avait pas été brûlée, il répondit: parce que j’ai récité le jour de l’incendie une invocation à propos de laquelle j’avais entendu le Prophète (P) dire: “Quiconque récite l’invocation suivante, le matin, il ne lui arrivera aucun mal durant cette journée, et quiconque la récitera le soir, il ne lui arrivera aucun mal cette nuit”:"},{"t":"tri","ar":"ما شآءَ اللهُ كانَ وَ مالَمْ يَشَاْ لَمْ يَكُنْ اَشْهَدُ اَنَّ اللهَ عَلى كُلِّ شَيْئٍ قَديرٌ وَ اَنَّ اللهَ قَدْ اَحاطَ بِكُلِّ شَيْئٍ عِلْماً اَللّهُمَّ اِنّي اَعُوذُ بِكَ مِنْ شَرِّ نَفْسي وَ مِنْ شَرِّ كُلِّ دآبَّةٍ اَنْتَ آخِذٌ بِناصِيَتِها اِنَّ رَبّي عَلى صِراطٍ مُسْتَقيمٍ *","tr":"Allâhumma Anta Rabbî, lâ Ilâha illâ Anta, ‘alayka tawakkaltu wa Anta Rabb-ul-‘Arch-il-‘adhîm. Mâ châ’-Allâhu kâna wa mâ lam yachi’ lam yakun. A‘lamu inna-llâha ‘alâ kulli chay’in Qadîr-un wa inna-llâha qad ahâta bi-kulli chay’in ‘ilman. Allâhumma innî a‘ûthu bika min charri-l-jinni wa-l-insi wa min charri kulli dabbatin Anta âkhithun bi-nâçiyatihâ, inna Rabbî ‘alâ çirâtin mustaqîm-in","fr":"O Allâh! Tu es mon Seigneur! Il n’y a de Dieu que Toi! C’est sur Toi que je compte totalement et Tu es le Seigneur du Trône immense! Ce qu’Allah veut est, et ce qu’Il ne veut pas, n’est pas. Je sais qu’Allah a Pouvoir sur toute chose et qu’Il entoure de Sa Science toute chose. O Allah! Je me protège par Toi contre le mal des djinns et contre le mal des humains, ainsi que contre le mal de tout être vivant que Tu tiens par son toupet. Mon Seigneur est certes sur un droit chemin"}]},"cp1-les-prieres-des-jours-de-la-semaine":{"source":"Les Clés des Paradis — Livre 1","title":"Les Prières des jours de la semaine","body":[],"prose":true},"cp1-la-priere-du-samedi":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Samedi","body":["■ L’Imam al-Hassan al-‘Askari (p), cité par Ibn Tâwûs, rapporte: “J’ai lu dans les écrits de mes ascendants (p) que quiconque accomplit le samedi quatre rak‘ah de prière et qu’il récite dans chacune d’elles les sourates (chapitres) al-Fâtihah, al-Tawhîd, ainsi que Âyat al-Kursî, Allah - Il est Puissant et Sublime - l’inscrit dans la position des prophètes, des martyrs et des serviteurs pieux. Quelle bonne compagnie!”"],"prose":true},"cp1-la-priere-du-dimanche":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Dimanche","body":["■ Selon l’Imam al-Hassan al-Askari (p): “Quiconque accomplit le dimanche quatre rak‘ah de prière et qu’il lit dans chacune d’elles les sourates al-Fâtihah, Tabârak (al-Mulk, No. 67), Allah lui accordera au Paradis la maison qu’il choisirait”"],"prose":true},"cp1-la-priere-du-lundi":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Lundi","body":["■ Selon l’Imam al-Hassan al-Askari (p): “Quiconque accomplit le lundi dix rak‘ah de prière et qu’il récite dans chacune d’elles, la sourate al-Fâtihah et 11 fois la sourate al-Tawhîd, Allah fera du jour de vendredi une source lumineuse qui illumine ce jour-là tellement le lieu de sa prière que toutes les créatures d’Allah l’en envieraient.”"],"prose":true},"cp1-la-priere-du-mardi":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Mardi","body":["■ Selon l’Imam al-Hasan al-Askari (p): “Quiconque accomplit le mardi six rak‘ah de prière et qu’il récite dans chacune d’elles la sourate al-Hamd, le verset de “Âman-ar-rasûlu” et la sourate al-Zalzalah (chapitre 99), Allah absout ses péchés jusqu’à ce qu’il en soit aussi purifié que le jour où sa mère l’a mis au monde.”"],"prose":true},"cp1-la-priere-du-mercredi":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Mercredi","body":["■ Selon l’Imam al-Hasan al-Askari (p): “Quiconque accomplit le mercredi quatre rak‘ah de prière et qu’il récite dans chacune d’elles les sourates al-Hamd, al-Ikhlâç et al-Qadr, Allah lui pardonnera tous ses péchés et le mariera à une houri aux grands yeux.”"],"prose":true},"cp1-la-priere-du-jeudi":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Jeudi","body":["■ Selon l’Imam al-Hasan al-Askari (p): “Quiconque accomplit le jeudi 10 rak‘ah de prière comprenant chacune la lecture de la sourate al-Fâtihah (une fois) et la sourate al-Tawhîd (11 fois), les Anges lui diront: “Demande ce que tu voudrais, tu l’auras”"],"prose":true},"cp1-la-priere-du-vendredi":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du Vendredi","body":["■ Selon l’Imam al-Hasan al-Askari (p): “Quiconque accomplit le vendredi 4 rak‘ah de prière comprenant chacune la lecture des sourates al-Fâtihah, al-Mulk (chapitre 67) et Hâ’ Mîm al-Sajdah, Allah le fera entrer dans Son Paradis, acceptera son intercession en faveur des membres de sa famille, lui évitera la pression de la tombe et la terreur du Jour de la Résurrection”. L’horaire de cette prière va du lever du soleil au coucher du soleil."],"prose":true},"cp1-la-priere-de-la-nuit-de-l-enterrement":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière de la nuit de l’enterrement","body":[{"t":"instruction","tx":"Selon un hadith du Prophète (P), cité par Ibn Tâwûs: «Le mort ne connaît pas une nuit plus dure que la première nuit de son enterrement. Faites donc miséricorde à vos morts en faisant l’aumône en leur faveur. Si vous n’en avez pas les moyens, accomplissez deux rak‘ah de prière dont la première comprend la lecture de la sourate al-Fâtihah et deux fois la sourate al-Tawhîd, et la seconde, la sourate al-Fâtihah et dix fois la sourate al-Takâthur (chapitre 102). Une fois la prière terminée dites:"},{"t":"tri","ar":"اَللّهُمَّ صَلِّ عَلى مُحَمَّد وَ آلِ مُحَمَّد وَابْعَثْ ثَوابَها اِلى قَبْرِ فُلان","tr":"Allâhumma çalli ‘alâ Muhammadin wa Âle Muhammadin wa-b‘ath thawâbihâ ilâ qabri ....(prononcez le nom complet du mort).","fr":"O mon Dieu! Prie sur Muhammad et sur la Famille de Muhammad et envoie-en la récompense spirituelle (le thawâb de cette prière) à la tombe de....(prononcez le nom complet du mort)"},{"t":"intro","tx":"Allah enverra alors tout de suite à sa tombe mille Anges dont chacun lui apportera une chemise et un manteau, et Il élargira l’étroitesse de la tombe, et ce jusqu’au Jour où l’on soufflera dans la Trompe (le Jour de la Résurrection). En outre, Allah mettra au crédit de celui qui fait cette prière la récompense d’un nombre de bonnes actions, égal au nombre des levers du soleil, et l’élèvera de quarante degrés »"},{"t":"instruction","tx":"■ Il y a une autre version de cette prière: Elle consiste elle aussi en deux rak‘ah dont la première comprend la lecture de la sourate al-Fâtihah et Âyat al-Kursî, et la seconde, la sourate al-Fâtihah et dix fois la sourate al-Qadr (chapitre 97). Une fois la prière terminée dites:"},{"t":"tri","ar":"اَللّهُمَّ صَلِّ عَلى مُحَمَّدٍ وَ آلِ مُحَمَّدٍ وَابْعَثْ ثَوابَها اِلى قَبْرِ فُلان","tr":"Allâhumma çalli ‘alâ Muhammadin wa Âle Muhammadin wa-b‘ath thawâbihâ ilâ qabri ...(prononcez le nom complet du mort).","fr":"O mon Dieu! Prie sur Muhammad et sur la Famille de Muhammad et envoie-en la récompense spirituelle (le thawâb de cette prière) à la tombe de....(prononcez le nom complet du mort)"}]},"cp1-devoirs-envers-les-morts":{"source":"Les Clés des Paradis — Livre 1","title":"Devoirs envers les morts","body":[{"t":"intro","tx":"■ Selon al-‘Allâmah al-Majlicî dans “Zâd al-Ma‘âd”, le croyant ne doit pas négliger de se rappeler ses proches morts, car ceux-ci n’ont plus la possibilité d’accomplir de bonnes actions et les actes de bienfaisance (pour se racheter) et espèrent vivement que leurs descendants, leurs proches et leurs frères croyants en général le font à leur place et en leur nom. Ils attendent d’eux un geste de bienfaisance de leur part et surtout leur du‘â’ lors de la Prière de la Nuit."},{"t":"intro","tx":"Le croyant doit faire le du‘â’ à ses parents après les Prières obligatoires et dans les lieux saints, sans oublier les bonnes oeuvres dédiées à leur mémoire. Car selon le Hadîth: “Peut-être un homme qui avait été noté comme ‘âq (désobéissant à ses parents) de leur vivant, sera-t-il considéré comme bâr (obéissant et bienfaiteur envers ses parents) après leur mort, grâce aux bonnes oeuvres qu’il aura accomplies en leur nom. De même un homme qui avait été noté comme bâr envers ses parents de leur vivant, serait-il enregistré comme ‘âq envers eux, à cause de son manque d’accomplissement d’actes de bienfaisance qui leur sont dus”."},{"t":"intro","tx":"Parmi les devoirs les plus importants qu’on doit accomplir envers les parents et les proches figurent l’acquittement de leurs dettes impayées et de toutes autres obligations non acquittées envers les gens ou envers Allah. Ainsi, on doit s’efforcer d’accomplir en leur nom (soit soi-même, soit en déléguant un autre -moyennant rémunération- pour le faire) un pèlerinage dû qu’ils auraient manqué ou tous autres actes d’adoration qu’ils auraient manqués. Selon un hadith sain (çahîh) l’Imam al-Sâdiq (p) accomplissait chaque nuit deux rak‘ah de prière dédiées à son fils, et chaque jour deux autres rak‘ah au nom et à la place de ses parents. Dans la première rak‘ah de chaque prière, il récitait après la sourate al-Hamd, la sourate al-Qadr (chapitre 97), et dans la seconde la sourate al-Kawthar (chapitre 108)."},{"t":"intro","tx":"■ Toujours selon l’Imam al-Sâdiq (p): “Il arrive que le mort qui se trouve en difficulté soit subitement soulagé et que l’on l’informe que ce soulagement est dû à la prière faite à son bénéfice par un tel frère croyant”. Et lorsque le rapporteur de ce hadith demanda à l’Imam s’il était possible qu’on accomplisse une prière de deux rak‘ah pour deux morts à la fois, il répondit par l’affirmative. Il dit également: “Le mort se réjouit du du‘â’ et de l’istigh-fâr faits en son nom autant que le vivant se réjouit d’un beau cadeau qu’on lui offre.”"},{"t":"intro","tx":"Et l’Imam d’ajouter: “La Prière, le jeûne, le Pèlerinage, l’aumône, l’acte de bienfaisance et le du‘â’ faits au nom d’un mort parviennent à sa tombe”. Il dit également: “La récompense (la rétribution = ajr) de ces actes (faits au nom d’un mort) bénéficie aussi bien au mort à qui ils sont destinés qu’à la personne qui les lui a dédiés.” Selon un autre hadith attribué à l’Imam al-Sâdiq (p): “Tout Musulman qui accomplit une oeuvre (acte de piété ou de bienfaisance) au bénéfice d’un mort, Allah lui accorde une double récompense tout en faisant parvenir la rétribution de cette oeuvre audit mort.”"},{"t":"intro","tx":"La prière dédiée aux deux parents décédés"},{"t":"instruction","tx":"Elle consiste en deux rak‘ah: dans la première rak‘ah on récite la sourate al-Hamd une fois et dix fois:"},{"t":"tri","ar":"رَبِّ اغْفِرْلي وَ لِوالِدَي وَ لِلْمُؤْمِنينَ يَوْمَ يَقُومُ الْحِسابُ ً","tr":"Rabbi-gh-fir lî wa liwâlidayya wa li-l-mu’minîna yawma yaqûm-ul-Hisâb","fr":"O mon Dieu pardonne-moi ainsi qu’à mes parents et aux croyants le Jour où le Compte sera établi,"},{"t":"instruction","tx":"et dans la seconde, une fois la sourate al-Hamd et dix fois:"},{"t":"tri","ar":"رَبِّ اغْفِرْلي وَ لِوالِدَي وَ لِمَنْ دَخَلَ بَيْتِيَ مُؤْمِناً وَ لِلْمُؤْمِنينَ وَ الْمُؤْمِناتِ","tr":"Rabbi-gh-fir lî wa liwâlidayya wa liman dakhala baytî mu’minan wa il-l-mu’minîna wa il-l-mu’minâti","fr":"O mon Dieu! Pardonne-moi, ainsi qu’à mes parents et à quiconque entre dans ma maison en croyant, et à tous les croyants et croyantes"},{"t":"instruction","tx":"Et une fois qu’on prononce le salâm qui marque la fin de la Prière, on récite dix fois:"},{"t":"tri","ar":"رَبِّ ارْحَمْهُما كَما رَبَّياني صَغيرا","tr":"Rabbi-rhamhumâ kamâ rabbayânî çaghîrâ","fr":"O mon Dieu! Couvre-les (mes deux parents) de Ta Miséricorde comme ils m’ont élevé tout petit"}]},"cp1-la-priere-de-l-affame":{"source":"Les Clés des Paradis — Livre 1","title":"La prière de l’affamé","body":["■ Selon l’Imam al-Sâdiq (p): «Quiconque souffre de la faim, qu’il fasse l’ablution (wudhû’) et deux rak‘ah de prière au terme desquelles il dit: “O mon Seigneur! J’ai faim! Nourris-moi”. Allah exauce sa prière immédiatement »"],"prose":true},"cp1-priere-contre-le-scepticisme-les-tentations-de-s":{"source":"Les Clés des Paradis — Livre 1","title":"Prière contre le scepticisme, les tentations de Satan et le doute obsessionnel","body":[{"t":"intro","tx":"■ Selon l’Imam al-Sâdiq (p), il ne s’écoule pas 40 jours pour un croyant sans qu’il ne soit atteint, au moins une fois par le scepticisme (hadîth al-nafs) (associationnisme). Lorsque cela arrive, il doit accomplir deux rak‘ah de prière et demander à Allah de l’en guérir."},{"t":"intro","tx":"■ Toujours selon l’Imam al-Sâdiq (p): «Lorsque Adam (p) se fut plaint auprès d’Allah du scepticisme, Jibrâ’îl (l’Archange Gabriel) descendit vers lui et lui dit: “Dis: lâ hawla wa lâ quwwata illâ billâh (لا حَوْلَ وَلا قُوَّةَ اِلاّ بِاللَّه) (il n’y a de Force ni de Pouvoir en dehors d’Allah)”. Adam s’exécuta et en guérit»"},{"t":"instruction","tx":"■ Selon l’Imam Mohammad al-Bâqir (p): «Un homme était venu se plaindre auprès du Prophète (P) des tentations de Satan, du scepticisme et d’une dette qui l’accablait, le Prophète (P) lui conseilla:"},{"t":"instruction","tx":"“Dis:"},{"t":"tri","ar":"تَوَّكَلْتُ عَلَى الْحَي الَّذي لا يَمُوتُ وَالْحَمْدُ للهِِ الَّذي لَمْ يَتَّخِذْ وَلَداً وَلَمْ يَكُنْ لَهُ شَريكٌ فِي الْمُلْكِ وَلَمْ يَكُنْ لَهُ وَلِي مِنَ الذُّلِّ وَكَبِّرْهُ تَكْبيراً","tr":"Tawakkaltu ‘alâ-l-Hayy-il-lathî lâ yamût-u wa-l-hamdu lillâh-il-lathî lam yattakhith waladan wa lam yakun lahu charîkun fî-l-Mulki wa lam yakun lahu waliyyun min-ath-thulli wa kabbirhu takbîrâ","fr":"Je m’en remets au Vivant qui ne S’est jamais attribué d’enfant et Qui n’a jamais eu de protecteur contre l’humiliation, et proclame hautement Sa Grandeur."},{"t":"intro","tx":"L’homme revint quelques jours plus tard et dit au Prophète (P): “Allah a écarté de moi le scepticisme, acquitté ma dette, et m’a fait sortir du besoin (de la pauvreté)”»"},{"t":"instruction","tx":"■ Pour conjurer les tentations de Satan encore, on peut réciter l’invocation suivante:"},{"t":"tri","ar":"هُوَ الاَْوَّلُ وَالآخِرُ وَالظّاهِرُ وَالْباطِنُ وَ هُوَ بِكُلِّ شَيءٍ عَليمٌ","tr":"Huwa-l-Awwalu wa Huwa-l-Âkhiru wa-l-dhâhiru wa-l-Bâtinu wa-Huwa bi-kulli chay’in ‘Alîm","fr":"Il est le Premier et Il est le Dernier, Il est le Manifeste et Il est le Caché, et Il est au courant de toute chose"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p), lorsqu’on est en proie aux tentations de Satan, on doit passer la main sur la poitrine et dire:"},{"t":"tri","ar":"بِسْمِ اللهِ وَ بِاللهِ مُحَمَّدٌ رَسُولُ اللهِ وَلاحَوْلَ وَ لا قُوَّةَ اِلاّ بِاللهِ الْعَلِي الْعَظيمِ اَللّهُمَّ امْسَحْ عَنّي ما اَحْذَرُ","tr":"Bism-illâhi wa bi-llâhi, Muhammadun Rasûl-ullâhi, wa lâ Hawla wa lâ Quwwata illâ billâh-il-‘Aliyy-il-‘Adhîm. Allâhumma-msah ‘annî mâ ah-thar-u","fr":"Au Nom d’Allah et par Allah! Muhammad est le Messager d’Allah. Et il n’y a de Force ni de Pouvoir en dehors d’Allah, le Très-Haut, le Sublime. O Allâh! Chasse de moi ce que je crains"},{"t":"intro","tx":"Puis on passe la main sur le ventre 3 fois."},{"t":"intro","tx":"■ D’autre part, on peut soigner le scepticisme par le lavage de la tête avec du lotus, l’utilisation du miswâk (pour nettoyer les dents), ou en mangeant des grenades et buvant de l’eau de pluie du mois d’avril"}]},"cp1-priere-de-demande-de-pardon-des-peches-istigh-fa":{"source":"Les Clés des Paradis — Livre 1","title":"Prière de demande de pardon des péchés (istigh-fâr)","body":["Elle consiste en deux rak‘ah de prière dont chacune comporte la récitation de la sourate al-Hamd (1 fois) et 60 fois la sourate al-Tawhîd.","■ Une autre prière de demande de pardon des péchés:","Selon Ibn Mas‘ûd, le Prophète (P) dit: “Quiconque accomplit la prière suivante le vendredi après Salât al-‘Açr (Prière de l’après-midi), ne quittera pas ce monde sans qu’Allah ne lui montre en songe le Paradis et la place qui lui y sera réservée:","Cette prière consiste en deux rak‘ah: dans la première on récite la sourate al-Hamd 1 fois, suivie de Âyat al-Kursî (le Verset du Trône) et de la sourate al-Falaq (chap. 113), 25 fois.","■ Le Prophète (P) dit:","« Si tu constates des difficultés dans ta subsistance et des ennuis dans tes affaires, confie tes difficultés à Allah et n’omets pas d’accomplir la Prière de l’istigh-fâr, laquelle consiste en deux rak‘ah: dans chaque rak‘ah récite la Sourate al-Hamd et la Sourate Innâ Anzalnâhu (Sourate al-Qadr = Le Destin) suivie de la formule Astagh-fir-ullâh (je demande pardon à Allah) quinze fois, puis fais le rukû‘ (agenouillement) et récites-y la même formule dix fois, à la manière de la Prière de Ja‘far al-Tayyâr (R). Après quoi Allah arrangera tes affaires »."],"prose":true},"cp1-la-priere-de-l-istikharah-au-tirage-au-sort":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière de l’Istikhârah au tirage au sort","body":[{"t":"instruction","tx":"Si on se trouve dans une situation où il est difficile de prendre une décision ou d’entreprendre une action, on peut recourir à l’istikhârah, c’est-à-dire demander l’aide d’Allah pour nous guider. Une des manières de solliciter l’assistance divine consiste à prendre six morceaux de papier: sur 3 d’entre eux on écrit la formule:"},{"t":"tri","fr":"Au Nom d’Allah, le Clément, le Miséricordieux. Le meilleur choix de la part d’Allah, le Puissant, le Sage pour...(Untel fils d’Untel) : Fais-le,"},{"t":"instruction","tx":"et on écrit dans les trois autres papiers:"},{"t":"intro","tx":"“Bism-illâh-ir-Rahmân-ir-Rahîm. Khîratun min-Allâh-il-‘Azîz-il-Hakîm li.... (pour Untel fils d’Untel): Lâ taf‘al”"},{"t":"intro","tx":"(Au Nom d’Allah, le Clément, le Miséricordieux. Le meilleur choix de la part d’Allah, le Puissant, le Sage pour...(Untel fils d’Untel): Ne le fais pas)."},{"t":"instruction","tx":"Puis, on plie les six papiers, on les dépose sous la natte de la prière et on accomplit deux rak‘ah de prière. Tout de suite après on fait une prosternation dans laquelle on récite cent fois: “Astakhîr-ullâha bi-Rahmatihi khîratan fî ‘âfiyah” (Je demande à Allah de choisir pour moi, par Sa Miséricorde le meilleur choix qui me préserve de tout mal). Puis on redresse le buste pour rester assis et on récite la formule:"},{"t":"tri","fr":"O mon Dieu! Choisis pour moi dans toutes mes affaires afin que Ton choix me mette à l’abri des difficultés et me préserve de tout mal."},{"t":"intro","tx":"Après quoi on mélange bien les morceaux de papier pliés et on en ramasse trois un par un. Si les trois premiers papiers ramassés portent tous la mention “fais-le”, cela signifie qu’il faut faire l’action pour laquelle on a sollicité l’aide d’Allah, et si tous les trois portent la mention “ne le fais pas”, on doit s’en abstenir. Mais si le premier papier tiré a la mention “fais-le”, le second “ne le fais pas”, on doit en tirer encore trois un par un. Si sur les cinq papiers tirés trois portent la mention “fais-le” et deux “ne le fais pas”, il faut accomplir l’action concernée, dans le cas contraire il faut s’en abstenir."},{"t":"intro","tx":"Il est à noter que “istikhârah” signifie la demande du bien. Lorsqu’on veut faire quelque chose on demande à Allah de nous guider dans notre choix. Selon le Hadith, on sollicite la guidance d’Allah dans de telles situations lors de la dernière sajdah (prosternation) de la Prière surérogatoire de la Nuit (Salât-ul-layl) en récitant cent fois: “Astakhîr-ullâha bi-Rahmatihi” (Je sollicite la guidance d’Allah, par Sa Miséricorde, pour faire le bon choix). De même il est recommandé de faire l’istikhârah lors de la dernière sajdah de la prière surérogatoire du matin, ainsi que dans chacune des rak‘ah des prières surérogatoires de midi."}]},"cp1-d-autres-methodes-de-faire-l-istikharah":{"source":"Les Clés des Paradis — Livre 1","title":"D’autres méthodes de faire l’Istikhârah","body":["■ Selon des Récits, l’Imam al-Mahdi (‘aj) faisait l’istikhârah par le chapelet. Cette méthode consiste à réciter d’abord, trois fois “Allâhumma çalli ‘alâ Muhammadin wa Âle Muhammad” et à fixer ensuite une partie quelconque du chapelet avec une main et une autre avec l’autre main, puis à dévider deux par deux les grains compris entre les deux mains. Si à la fin il reste un grain, le résultat est bon (cela signifie qu’il faut accomplir l’action pour laquelle on a sollicité l’aide d’Allah) et s’il en reste deux, le résultat est mauvais (il faut s’abstenir de l’action projetée).","Il y a une autre variante de cette méthode. Elle consiste à réciter tout d’abord une sourate quelconque du Coran suivie d’une invocation quelconque, puis à poser la main à un endroit du chapelet et à en dévider les grains à partir de cet endroit huit par huit. Si à la fin il reste un grain, le résultat est considéré comme bon en général. S’il en reste deux, cela équivaut à une interdiction (d’exécuter l’action projetée). S’il en reste trois, le résultat est neutre (on peut indifféremment faire ou ne pas faire l’action projetée). S’il en reste quatre, cela équivaut à deux fois l’interdiction (interdiction confirmée). S’il en reste cinq, cela signifie que l’exécution de l’action projetée comporte la fatigue ou le blâme. S’il reste six grains, cela signifie que le résultat est très bon et qu’il faut accomplir l’action projetée sans tarder. S’il en reste sept, le résultat est identique au cas de figure où il en reste cinq (fatigue ou blâme). Et s’il en reste huit, cela signifie que l’interdiction d’exécuter l’action projetée est confirmée quatre fois."],"prose":true},"cp1-istikharah-ou-presage-par-le-coran":{"source":"Les Clés des Paradis — Livre 1","title":"Istikhârah ou présage par le Coran","body":[{"t":"instruction","tx":"■ Selon un hadith attribué au Prophète (P): “Si tu veux tirer présage du Livre d’Allah - Il est Puissant et Sublime, récite la sourate al-Ikhlâç 3 fois, puis dis 3 fois:"},{"t":"tri","ar":"اَللّـهُمَّ صَلِّ عَلى مُحَمَّد وَآلِ مُحَمَّد","tr":"Allâhumma çalli ‘alâ Muhammadin wa Âle Muhammad-in","fr":"O Allah, prie sur Muhammad et sur les Membres de sa Famille,"},{"t":"instruction","tx":"et ensuite fais l’invocation suivante:"},{"t":"tri","fr":"O mon Dieu! Je cherche présage dans Ton Livre et je me confie à Toi! Montre-moi donc dans Ton Livre ce qui est dissimulé de Ton Secret caché dans Ton Mystère."},{"t":"intro","tx":"Après quoi ouvre le Coran et tire présage de la première ligne de la page de droite”"},{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p) si quelqu’un veut faire l’istikhârah dans le Noble Livre (tirer présage ou augure du Coran), qu’il dise:"},{"t":"tri","fr":"Au Nom d’Allah, le Tout-Miséricordieux, le Très-Miséricordieux,"},{"t":"instruction","tx":"suivi de l’invocation suivante:"},{"t":"tri","fr":"S’il est (écrit) dans Ton Décret et Ta Décision que Tu fasses aux adeptes des Membres de la Famille de Muhammad (que la Paix soit sur eux) la faveur de faire réapparaître Ton Ami et Ton Argument (le Mahdi attendu) auprès de Ta création, fais que nous tombions sur un verset de Ton Livre, susceptible de nous l’indiquer"},{"t":"intro","tx":"Puis, il doit ouvrir le Coran au hasard, compter à partir de la partie ouverte 6 feuilles suivantes. Et sur la septième feuille, il doit lire ce qui suit les six premières lignes, le présage concernant l’objet de son istikhârah."}]},"cp1-istikharah-par-le-chapelet-et-le-nombre":{"source":"Les Clés des Paradis — Livre 1","title":"Istikhârah par le chapelet et le nombre","body":[{"t":"instruction","tx":"■ Selon un hadith attribué à l’Imam al-Mahdi (‘aj), pour faire l’istikhârah, on récite au moins une fois (sinon 10 fois, ou à défaut 3 fois) la sourate al-Hamd (al-Fâtihah), puis 10 fois la sourate al-Qadr (Chap. 97), et ensuite 3 fois l’invocation suivante:"},{"t":"tri","ar":"اَللّهُمَّ اِنّي اَسْتَخيرُكَ لِعِلْمِكَ بِعاقِبَةِ الاُْمُورِ وَ اَسْتَشيرُكَ ِحُسْنِ ظَنّي بِكَ فِي الْمَاْمُولِ وَالْمَحْذُورِ","tr":"Allâhumma innî astakhiruka li-‘Ilmika bi-‘âqibat-il-umûri, wa astachîruka li-husni dhannî bika fî-l-ma’mûli wa-l-mah-thûri...","fr":"Mon Dieu! Je Te demande le bon augure, parce que Tu connais les conséquences des actes, et je Te consulte, parce que j’ai bonne foi en Toi concernant ce qu’on espère et ce qu’on craint..."},{"t":"intro","tx":"Ensuite, on forme mentalement l’intention (niyyah) et on délimite au hasard une portion du chapelet. Si le nombre de grains est pair, le résultat est négatif (il faut abandonner le projet) et s’il est impair, le résultat est positif (on peut exécuter le projet), ou vice versa, selon la règle qu’on se fixe préalablement."}]},"cp1-l-istikharah-consultation-divine-d-apres-le-prop":{"source":"Les Clés des Paradis — Livre 1","title":"L’Istikhârah (consultation divine) d’après le Prophète (P)","body":["■ Jâbir Ibn ‘Abdullâh témoigne: Le Messager d’Allah (P) nous apprenait l’istikhârah comme il nous apprenait une sourate (chapitre) coranique. Il (le Prophète) disait:","«Si l’un de vous a une décision (dont on ne connaît pas les conséquences) à prendre, qu’il accomplisse deux rak‘ah de Prière recommandée, puis qu’il dise: “O Allah! Je Te consulte par Ta Science, je fais appel à Ton Pouvoir, et je Te demande de Ta Grâce grandiose - car Toi, Tu as le Pouvoir, moi non, Toi, Tu es Omniscient, moi je ne sais rien, Tu es le Connaisseur des Mystères. Si Tu vois que cette affaire (mentionnez la décision qui vous préoccupe) est bien pour moi, relativement à ma Religion, à ma vie et à mon destin, fais qu’elle soit à ma portée, facilite-la et bénis-la pour moi, et si Tu vois qu’elle est un mal pour moi relativement à ma Religion, ma vie ou mon destin, écarte-la de moi et écarte-m’en, et dirige-moi alors vers le bien là où il se trouve, puis fais-m’en satisfait”»."],"prose":true},"cp1-invocation-lors-de-la-circoncision":{"source":"Les Clés des Paradis — Livre 1","title":"Invocation lors de la circoncision","body":[{"t":"instruction","tx":"■ Selon l’Imam al-Sâdiq (p) il est recommandé de réciter l’invocation suivante lors de la circoncision d’un enfant (et même après la circoncision si l’on omet de le faire tout de suite):"},{"t":"tri","ar":"اَللّهُمَّ هذِهِ سُنَّتُكَ وَ سُنَّةُ نَبِيِّكَ صَلَواتُكَ عَلَيْهِ وَ آلِهِ وَاتِّباعٌ مِنّا لَكَ وَ لِنَبِّيِكَ بِمَشِيَّتِكَ وَ بِاِرادَتِكَ وَ قَضآئِكَ لاَِمْر اَرَدْتَهُ وَ قَضآءً حَتَمْتَهُ وَ اَمْر اَنْفَذْتَهُ وَ اَذَقْتَهُ حَرَّ الْحَديدِ في خِتانِهِ وَ حِجامَتِهِ بِاَمْرٍ اَنْتَ اَعْرَفُ بِهِ مِنّي اَللّهُمَّ فَطَهِّرْهُ مِنَ الذُّنُوبِ وَزِدْ في عُمْرِهِ وَادْفَعِ الاْفاتِ عَنْ بَدَنِهِ وَالاَْوْجاعَ عَنْ جِسْمِهِ وَ زِدْهُ مِنَ الْغِنى وَ ادْفَعْ عَنْهُ الْفَقْرَ فَاِنَّكَ تَعْلَمُ وَلانَعْلَمُ","tr":"Allâhumma hâthihi Sunnatuka wa sunnatu nabiyyika çalawâtuka ‘alayhi wa âlihi, wa-t-tibâ‘un minnâ laka wa li-nabiyyika bi-Machî’atika wa bi-Irâdatika wa Qadhâ’ika, li-amrin aradtahu wa qadhâ’in hatamtahu wa amrin anfath-tahu wa athiqtahu harr-al-hadîdi fî khitânihi wa hijâmatihi bi-amrin Anta a‘rafu bihi minnî. Allâhumma fa-tahhirhu min-ath-thunûbi wa zid fî ‘umrihi wa-dfa‘-il-âfâti ‘an badanihi wa-l-awjâ‘a ‘an jismihi, wa zid-hu min-al-ghinâ wa-dfa‘ ‘anhu-l-faqra, fa-innaka ta‘lamu wa lâ na‘lamu","fr":"O Allah! Ceci est Ta Législation et la sunna (la Tradition) de Ton Prophète - que Tes Prières soient sur lui et sur les Membres de sa Famille - et l’acquittement de notre part, par obéissance à Toi et à Ton Prophète, selon Ta Volonté, Ton Dessein et Ton Décret, d’une chose que Tu as voulue et un décret que Tu as rendu obligatoire, et par laquelle Tu fais goûter (à cet enfant) la chaleur du fer lors de la circoncision et du saignement (de la ventouse), pour une raison que Tu connais mieux que moi. O Allah! Purifie-le donc de ses péchés, prolonge sa vie, éloigne de son organisme les maladies et les douleurs de son corps. Augmente sa richesse et éloigne de lui la pauvreté. Car Tu sais et nous ne savons pas"}]},"cp1-la-priere-du-besoin":{"source":"Les Clés des Paradis — Livre 1","title":"La Prière du besoin","body":[{"t":"intro","tx":"■ Selon al-Râwandî, un jour l’Imam Zayn al-‘Abidine (p) a vu un homme assis près de la porte d’un nanti. Aussi lui demanda-t-il: “Pourquoi t’assois-tu devant la porte de ce puissant nanti?” “Le besoin”, lui répondit l’homme. L’Imam (p) lui dit alors: “Lève-toi! Je vais te guider vers une porte bien meilleure que celle-ci”. Il l’amena ainsi à la Mosquée du Prophète (P) et lui dit: “Mets-toi face à la Qiblah (la direction de la Mecque) pour accomplir deux rak‘ah de prière. Puis lève tes mains vers Allah -Il est Puissant et Glorieux- et après avoir fait Ses louanges et prié sur Son Messager, supplie-Le avec le dernier verset de la sourate al-Hachr, les six premiers versets de la sourate al-Hadîd, et deux versets de la sourate Âle ‘Imrâne. Après quoi demande à Allah ce dont tu as besoin, Il te donnera tout ce que tu lui demanderas”."},{"t":"intro","tx":"■ Selon Amîr al-Mu’minine, l’Imam Ali (p): “Si l’un d’entre vous a un besoin, qu’il le demande à Allah, le jeudi, tôt le matin, et qu’il récite, en sortant de sa maison le dernier verset de la sourate Âle ‘Imrâne, le verset du Trône (Âyat al-Kursî), la sourate al-Qadr et la sourate al-Hamd”"},{"t":"instruction","tx":"■ Une autre prière du besoin consiste en l’accomplissement de quatre rak‘ah comprenant le qunût et les autres piliers de la prière régulière:"},{"t":"instruction","tx":"- Dans la première rak‘ah on récite la sourate al-Hamd suivie de:"},{"t":"tri","ar":"حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ(173)(ال عمران(","tr":"Hasbunâ-llâhu wa ni‘m-al-Wakîl","fr":" sept fois"},{"t":"intro","tx":"(Allah nous suffit. Quel excellent Protecteur!)"},{"t":"instruction","tx":"- dans la deuxième, la sourate al-Hamd suivie de:"},{"t":"tri","ar":"مَا شَاءَ اللَّهُ لاَ قُوَّةَ إِلاَّ بِاللَّهِ إِنْ تَرَنِ َأَنَا أَقَلَّ مِنْكَ مَالاً وَوَلَدًا(39) (سورة الكهف(","tr":"mâ châ’a-llâhu, lâ quwwata illâ billâhi, in tarani anâ aqalla minka mâlan wa waladan","fr":"“Telle est la Volonté d’Allah! Il n’y a de puissance qu’en Allah! Si tu me vois moins pourvu que toi en biens et en enfants” (sept fois)"},{"t":"instruction","tx":"- dans la troisième, la sourate al-Hamd suivie de:"},{"t":"tri","ar":"لاَ إِلَهَ إِلاَّ أَنْتَ سُبْحَانَكَ إِنِّي كُنتُ مِنْ الظَّالِمِينَ(الانبياء 187(","tr":"Lâ ilâha illâ Anta Subhânaka innî kuntu min-adh-dhâlimîn-a","fr":"sept fois"},{"t":"intro","tx":"(Il n’y a de Dieu que Toi! Gloire à Toi! Oui, j’étais au nombre des injustes)"},{"t":"instruction","tx":"- dans la quatrième la sourate al-Hamd suivie de:"},{"t":"tri","ar":"وَأُفَوِّضُ أَمْرِي إِلَى اللَّهِ إِنَّ اللَّهَ بَصِيرٌ بِالْعِبَادِ(44) (سورة غافر(","tr":"Ufawwidhu amrî ila-llâhi, inna-llâha Baçîrun bi-l-‘ibâd-i","fr":"sept fois"},{"t":"intro","tx":"(Je confie mon sort à Allah. Allah voit parfaitement Ses serviteurs)"}]},"cp1-priere-pour-se-sortir-d-une-situation-difficile":{"source":"Les Clés des Paradis — Livre 1","title":"Prière pour se sortir d’une situation difficile","body":["L’Imam al-Sâdiq (p) dit: “Si tu te trouves dans une situation difficile dont tu ne peux pas te sortir, accomplis à midi deux rak‘ah de prière, dont la première comporte la lecture de la sourate al-Hamd, la sourate al-Tawhîd (chap. 112), et la sourate al-Fat-h (chap. 48), et la seconde, la sourate al-Hamd, la sourate al-Tawhîd, et la sourate al-Charh (chap. 94).”"],"prose":true},"cp1-priere-pour-augmenter-les-moyens-de-subsistance":{"source":"Les Clés des Paradis — Livre 1","title":"Prière pour augmenter les moyens de subsistance (rizq)","body":[{"t":"instruction","tx":"■ Selon la Tradition, un homme vint voir le Prophète et se plaignit: “O Messager d’Allah! J’ai une grande famille. Je suis accablé de dettes et je suis dans la gêne. Apprends-moi donc un du‘â’ par lequel je prierais Allah -Le Puissant et le Sublime- de me fournir les moyens financiers de régler ma dette et de subvenir aux besoins de ma famille nombreuse.” Le Prophète (P) lui dit: “O Serviteur d’Allah (Abdullâh)! Fais le wudhû’ (ablution) selon toutes ses règles et accomplis deux rak‘ah de prière comportant le rukû‘ (génuflexion) et le sujûd (prosternation). Après quoi dis:"},{"t":"tri","ar":"يا ماجِدُ يا واحِدُ يا كَريمُ اَتَوَجَّهُ اِلَيْكَ بِمُحَمَّدٍ نَبِيِّكَ نَبِيِّ الرَّحْمَةِ صَلَّى اللهُ عَلَيْهِ وَ آلِهِ يا مُحَمَّدُ يا رَسُولَ اللهِ اِنّي اَتَوَجَّهُ بِكَ اِلَى اللهِ رَبّي وَ رَبِّكَ وَ رَبِّ كُلِّ شَيْئٍ وَ اَسْأَلُكَ اللّهُمَّ اَنْ تُصَلِّيَ عَلى مُحَمَّد وَ اَهْلِ بَيْتِهِ وَ اَسْأَلُكَ نَفْحَةً كَريمَةً مِنْ نَفَحاتِكَ وَ فَتْحاً يَسيراً وَ رِزْقاً واسِعاً اَلُمُّ بِهِ شَعَثي وَ اَقْضي بِهِ دَيْني وَاَسْتَعينُ بِهِ عَلى عِيالي","tr":"Yâ Mâjidu yâ Wâhidu yâ Karîmu! Atawajjahu ilayka bi-Muhammadin nabiyyika, nabiyy-il-rahmati, çallâ-llâhu ‘alayhi wa âlihi! Yâ Muhammadu yâ rasûl-Allâh! Innî atawajjahu bika ilâ-llâhi Rabbî wa Rabbika wa Rabbi kulli chay’in, wa as’aluka Allâhumma an tuçalliyya ‘alâ Muhammadin wa Ahli Baytihi wa as’aluka Naf-hatan karîmatan min Nafahâtuka wa fat-han yasîran wa rizqan wâsi‘an alummu bihi cha‘thî wa aq-dhî bihi daynî wa asta‘înu bihi ‘alâ ‘iyâlî","fr":"O Glorifié! O Un! O Généreux! Je me dirige vers Toi en Te suppliant par l’amour de Muhammad, Ton Prophète, le Prophète de la Miséricorde - que la prière d’Allah soit sur lui et sur sa Famille. O Muhammad! O Messager d’Allah! Je m’appuie sur toi pour me diriger vers Allah, mon Seigneur, ton Seigneur et le Seigneur de toute chose. Et je Te demande, O Allah, de prier sur Muhammad et sur les membres de sa Famille, et je Te demande aussi (de m’accorder) un souffle généreux de Tes Souffles, une conquête facile, et de larges moyens de subsistance par lesquels je pourrais sortir de mon désarroi, acquitter ma dette et subvenir aux besoins de ma famille."},{"t":"intro","tx":"■ Une autre prière pour augmenter la subsistance (rizq)"},{"t":"instruction","tx":"Lorsqu’on s’apprête à aller à son lieu de travail, on passe d’abord par une mosquée pour accomplir une prière de deux rak‘ah et une autre de quatre rak‘ah. Puis on récite cette supplication:"},{"t":"tri","ar":"غَدَوْتُ بِحَوْلِ اللّهِ وَ قُوَّتِهِ وَ غَدَوْتُ بِلا حَوْل مِنّي وَلا قُوَّة وَلكِنْ بِحَولِكَ وَ قُوَّتِكَ يا رَبِّ اَللّهُمَّ اِنّي عَبْدُكَ اَلْتَمِسُ مِنْ فَضْلِكَ كَما اَمَرْتَني فَيَسِّرْ لي ذلِكَ وَ اَنَا خافِضٌ في عافِيَتِكَ","tr":"Ghadawtu bi-Hawl-illâhi wa Quwwatihi wa ghadawtu bilâ hawlin minnî wa lâ quwwatin, wa lâkin bi-Hawlika wa Quwwatika, Yâ Rabbi. Allâhumma innî ‘abduka, altamisu min fadh-lika kamâ amartanî, fayassîr lî thâlika wa anâ khâ’idhun fî ‘Âfiyatika","fr":"Je me trouve de bon matin par le Pouvoir et la Force d’Allah. Je ne me trouve pas de bon matin par mon pouvoir et ma force personnels, mais par Ton Pouvoir et Ta Force, O Seigneur! O Allâh! Je suis Ton serviteur, et je Te demande de m’accorder un peu de Ta Grâce, comme Tu m’as ordonné de le faire! Accorde-le-moi donc alors que je suis entré dans la sphère de Ta Générosité"},{"t":"intro","tx":"■ Il y a une autre prière pour l’augmentation du rizq. Elle consiste en 2 rak‘ah: dans la première on récite la sourate al-Hamd une fois, suivie de la sourate al-Kawthar (Chap. 108) trois fois, et dans la seconde la sourate al-Hamd une fois, suivie de la sourate al-Falaq (chap. 113) 3 fois et de la sourate al-Nâs (Chap. 114) 3 fois."}]},"cp1-du-a-pour-le-rizq-moyen-de-subsistance":{"source":"Les Clés des Paradis — Livre 1","title":"Du‘â’ pour le rizq (moyen de subsistance)","body":[{"t":"instruction","tx":"■ Selon l’Imam al-Bâqir (p) pour demander à Allah d’assurer ou d’augmenter vos moyens de subsistance, récitez le du‘â’ suivant en vous prosternant:"},{"t":"tri","ar":"يا خَيْرَ الْمَسْئُولينَ وَ يا خَيْرَ الْمُعْطينَ اُرْزُقْني وَارْزُقْ عِيالي مِنْ فَضْلِكَ فَاِنَّكَ ذُوالْفَضْلِ الْعَظيمِ","tr":"Yâ Khayr-al-Mas’ûlîn-a wa Yâ Khayr-al-Mu‘tîn-a, irzuqnî wa-rzuq ‘iyâlî min Fadhlik-a, fa-Innaka thu-l-Fadhl-il-‘Adhîm-i","fr":"O le Meilleur des sollicités et le Meilleur des donateurs! Accorde-moi, ainsi qu’à ma famille, par Ta Grâce, les moyens de subsistance! Tu es, certes, le Maître de la Grâce abondante"},{"t":"instruction","tx":"■ Ibn Baçîr témoigne: “Je me suis plaint auprès de l’Imam al-Sâdiq (p) du fait que je me trouvais dans le besoin et je lui ai demandé de m’apprendre un du‘â’ qui amène les moyens de subsistance. Il m’a appris le du‘â’ suivant, à réciter pendant la prosternation de la Prière de l’après-minuit (çalât-ul-layl). Je me suis exécuté et depuis lors je ne me suis jamais retrouvé dans la gêne”:"},{"t":"tri","ar":"يا خَيْرَ مَدْعُوٍّ وَ يا خَيْرَ مَسْئُولٍ وَ يا اَوْسَعَ مَنْ اَعْطى وَ يا خَيْرَ مُرْتَجى اُرْزُقْني وَ اَوسِعْ عَلَيَّ مِنْ رِزْقِكَ وَسَبِّبْ لي رِزْقاً مِنْ قِبَلِكَ اِنَّكَ عَلى كُلِّ شَئٍٍْ قَديرٌ","tr":"Yâ Khayra Mad‘uwwin wa Yâ Khayra Mas’ûl-in, wa Yâ Awsa‘a man a‘tâ wa Yâ Khayra Murtajâ! Urzuqnî wa awsi‘ ‘alayya min Rizqika wa sabbib lî rizqan min Qibalika, Innaka ‘alâ kulli chay’in Qadîr","fr":"O le Meilleur de ceux qu’on prie et le Meilleur de ceux qu’on sollicite! O le plus Généreux des donateurs et le Meilleur de ceux qu’on implore! Accorde-moi les moyens de subsistance et trouve-moi de Ta Part le moyen de gagner ma vie! Tu as certes le Pouvoir sur toute chose"},{"t":"instruction","tx":"■ Il est rapporté que le Prophète (P) recommanda le du‘â’ suivant pour solliciter d’Allah les moyens de subsistance:"},{"t":"tri","ar":"يا رازِقَ الْمُقِلّينَ وَ يا راحِمَ الْمَساكينَ وَ يا وَلِي الْمُؤْمِنينَ وَ يا ذَا الْقُوَّةِ الْمَتينَ صَلِّ عَلى مُحَمَّد وَ اَهْلِ بَيْتِهِ وَارْزُقْني وَ عافِني وَ اكْفِني ما اَهَمَّني","tr":"Yâ Râziq-al-muqillîn-a wa Yâ Râhim-al-masâkîn-a wa Yâ Waliyy-al-mu’minîn-a wa Yâ Thâ-l-Quwwat-il-Matîn-a! çalli ‘alâ Muhammadin wa Ahli Baytihi, wa-rzuqnî wa ‘âfinî wa-kfinî mâ ahammanî","fr":"O Pourvoyeur de subsistance des pauvres! O Miséricordieux envers les indigents! O Ami des croyants! O le Détenteur de la Force, l’Inébranlable! Prie sur Muhammad et sur les Gens de sa Famille, accorde-moi les moyens de subsistance, assure-moi la sécurité et épargne-moi ce qui me préoccupe."}]},"cp1-du-a-pour-s-acquitter-des-dettes":{"source":"Les Clés des Paradis — Livre 1","title":"Du‘â’ pour s’acquitter des dettes","body":[{"t":"instruction","tx":"■ L’Imam Mûsâ al-Kâdhim (p) recommanda l’invocation suivante pour s’acquitter des dettes:"},{"t":"tri","ar":"اَللّهُمَّ ارْدُدْ اِلى جَميعِ خَلْقِكَ مَظالِمَهُمُ الَّتي قِبَلي صَغيرَها وَ كَبيرَها في يُسْر مِنْكَ وَ عافِيَة وَ مالَمْ تَبْلُغْهُ قُوَّتي وَ لَمْ تَسَعْهُ ذاتُ يَدي وَ لَمْ يَقْوَ عَلَيْهِ بَدَني وَ يَقيني وَ نَفْسي فَاَدِّهِ عَنّي مِنْ جَزيلِ ما عِنْدَكَ مِنْ فَضْلِكَ ثُمَّ لاتُخَلِّفْ عَلَي مِنْهُ شَيْئاً تَقْضيهِ مِنْ حَسَناتي يا اَرْحَمَ الرّاحمِينَ اَشْهَدُ اَنْ لا اِلهَ اِلاَّ اللهُ وَحْدَهُ لا شَريكَ لَهُ وَ اَشْهَدُ اَنَّ مُحَمَّداً عَبْدُهُ وَ رَسُولُهُ وَ اَنَّ الدّينَ كَما شَرَعَ وَ اَنَّ الاِْسْلامَ كَما وَصَفَ وَ اَنَّ الْكِتابَ كَما اَنْزَلَ وَ اَنَّ الْقَوْلَ كَما حَدَّثَ وَ اَنَّ اللهَ هُوَ الْحَقُّ الْمُبينُ ذَكَرَ اللهُ مُحَمَّداً وَ اَهْلَ بَيْتِهِ بِخَيْر وَ حَيّا مُحَمَّداً وَ اَهْلَ بَيْتِهِ بِالسَّلامِ.","tr":"Allâhumma ardud ilâ jamî‘i khalqika madhâlimahum-ul-latî qibalî çaghîrihâ wa kabîrihâ fî yusrin minka wa ‘âfiyah, wa mâ lam tablugh-hu quwwatî wa lam tasa‘hu thâtu yadî wa taqwa ‘alayhi badanî wa yaqînî wa nafsî fa’addihi ‘annî min jazîli mâ ‘indaka min fadhlika, thumma lâ tukhallifu ‘alayya minhu chay’an tuq-dhîhi min hasanâtî, Yâ Arham-ar-râhimîn-a. Ach-hadu anna Muhammadan ‘abduhu wa Rasûluhu, wa inna-d-dîna kamâ chara‘a wa inna-l-Islâma kamâ waçafa wa inna-l-Kitâba kamâ anzala wa anna-l-qawla kamâ hadatha wa inna-llâha Huwa-l-Haqq-ul-Mubîn-u. Thakara-llâhu Muhammadan wa Ahli Baytihi bi-khayrin wa hayyâ Muhammadan wa Ahli Baytihi bi-s-salâmi","fr":"O Allah! Fais que les droits (dettes), majeurs ou mineurs, que tous Tes serviteurs ont sur moi soient acquittés, par Ta Grâce, sans difficulté et en toute sécurité. Et si la portée de ma force, la largesse de ma main, la capacité de mon corps, de ma certitude et de mon âme ne me permettaient pas d’acquitter une partie de ces droits, acquitte-la alors à ma place (en la prélevant) sur la profusion de Ta Bienveillance, et n’en laisse rien qui puisse être prélevé sur mes actes de bienfaisance, O le Plus Miséricordieux des miséricordieux! J’atteste que Muhammad est le Serviteur et le Messager d’Allah, que la Religion est telle qu’elle a été décrétée, que l’Islam est tel qu’il a été décrit, que le Livre est tel qu’il a été révélé, que la Parole est telle qu’elle a été dite, qu’Allah est la Vérité évidente. Allah a mentionné en bien Muhammad et les Gens de sa Famille, et Il a salué par le Salâm Muhammad et les Gens de sa Famille."},{"t":"instruction","tx":"■ Un homme se plaignit un jour auprès de ‘Isâ Ibn Maryam (Jésus) (p), des lourdes dettes qui l’accablaient. Le Prophète ‘Isâ (p) lui recommanda de lire le du‘â’ suivant et lui promit: “La récitation de ce du‘â’ appelle Allah à acquitter ta dette, même si elle était si considérable qu’elle couvrirait la terre”:"},{"t":"tri","ar":"اَللَّهُمَّ يا فَارِجَ الهَمِّ وَمُنَفِّسَ الغّمِّ وَمُذْهِبَ الاَحْزانِ وَ مُجيبَ دَعْوَةِ المُضْطَرِّينَ؛ يا رَحْمانَ الدُّنيا وَ الآخِرَةِ وَرَحِيمَهُما؛ اَنْتَ رَحْماني وَرَحْمان كُلِّ شَيْءٍ فَارْحَمْني رَحْمَةً تُغْنيني بِها عَنْ رَحْمِةِ مَنْ سِوَاكَ وَتَقْضي بِها عَنِّي الدَّيْنَ","tr":"Allâhumma Yâ Fârij-al-hammi wa Munaffis-al-ghammi wa muth-hib-al-ahzâni, wa Mujîbâ da‘wat-il-mudh-tarrîna! Yâ Rahmân-id-dunyâ wa-l-âkhirati wa Rahîmahumâ, Anta Rahmânî wa Rahmânu kulli chay’in, fa-rhamnî rahmatan tughnînî bi-hâ ‘an rahmati man siwâka wa taq-dhî bihâ ‘annî-d-dayn-a","fr":"O Allah! O Toi qui dissipes le souci, qui soulages l’angoisse, qui éloignes les afflictions, qui exauces les prières de demande des nécessiteux! O le Tout-Miséricordieux et le Très-Miséricordieux de ce monde et de l’Au-delà! Tu es mon Tout-Miséricordieux et le Tout-Miséricordieux de toute chose! Couvre-moi donc d’une Miséricorde grâce à laquelle je me passerai de la miséricorde de tout autre que Toi, et par laquelle Tu acquitteras ma dette!"}]}},"prepend":{}};
